package com.atlashub.pay.txquery.application.queries.GetTransactionByReference;import com.atlashub.pay.txquery.application.queries.TransactionResultMapper;import com.atlashub.pay.txquery.application.queries.TransactionResults.TransactionResult;import com.atlashub.pay.txquery.domain.exceptions.TransactionRecordNotFoundException;import com.atlashub.pay.txquery.domain.repositories.TransactionRecordRepository;import com.atlashub.shared.application.usecase.Query;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.stereotype.Component;@Component public class GetTransactionByReferenceHandler extends Query<GetTransactionByReferenceQuery,TransactionResult>{private final TransactionRecordRepository repository;private final TransactionResultMapper mapper;public GetTransactionByReferenceHandler(TransactionRecordRepository r,TransactionResultMapper m){repository=r;mapper=m;}@Override @PreAuthorize("hasAuthority('pay:ledger:read')")public TransactionResult execute(GetTransactionByReferenceQuery q){return mapper.map(repository.findByOrganizationIdAndEnvironmentAndReference(q.organizationId(),q.environment(),q.reference()).orElseThrow(()->new TransactionRecordNotFoundException(q.reference())));}}
